using System;using System.Linq;using System.Text.Json;using MotorwaysSim;
class Check {static void Main(){var r=Rules.ForVersion(GameVersion.OriginalReference);r.EnableCityGrowth=false;var w=new TrafficWorld(40,false,r);w.Reset(40,ScenarioKind.EmptyLab);w.Inventory[4]=1;var c=new Cell(15,15);var corner=new Cell(14,14);w.Build(BuildTool.Road,corner);w.Build(BuildTool.Roundabout,c);var ring=w.Roundabouts[0].Ring;var forward=w.FindRoute(ring[0],ring[1]);var reverse=w.FindRoute(ring[1],ring[0]);Console.WriteLine(JsonSerializer.Serialize(new{fixture="corner ordinary road preexists at (14,14)",cornerDegree=w.Degree(corner),northToWest=forward.Select(x=>x.ToString()),westToNorth=reverse.Select(x=>x.ToString()),northToWestCost=w.RouteCost(forward),ringSpeed=w.LaneSpeed(ring[0],0,0)}));
w.Build(BuildTool.Remove,corner);forward=w.FindRoute(ring[0],ring[1]);reverse=w.FindRoute(ring[1],ring[0]);Console.WriteLine(JsonSerializer.Serialize(new{fixture="bare directed ring",forwardCells=forward.Count,reverseCells=reverse.Count,routeCost=w.RouteCost(forward),physicalSpeed=w.LaneSpeed(ring[0],0,0)}));
}}
